<script setup lang="ts">
import { computed, ref } from 'vue'
import { pct, number, selectedLabel } from './format'
const props = defineProps<{ agent: any }>()
defineEmits<{ inspect: [id: string] }>()
const active = ref(0)
const member = computed(() => props.agent.method.population[active.value])
const choices = computed(() => props.agent.method.parentChoices.filter((row: any) => row.parent_index === member.value.index))
</script>
<template>
  <div data-method="gepa">
    <div class="sx-stats"><div class="sx-stat"><span>Recorded population</span><strong>{{ agent.method.population.length }}</strong><small>Mean score and per-task coverage</small></div><div class="sx-stat"><span>Metric budget consumed</span><strong>{{ number(agent.method.metricCalls) }}</strong><small>{{ agent.method.iterations }} search iterations</small></div><div class="sx-stat"><span>Coverage columns</span><strong>{{ agent.method.tasks }}</strong><small>Development tasks, including ties</small></div></div>
    <section class="sx-panel"><h2>Task-winner coverage</h2><p>Rows can cover different tasks despite similar mean scores. Copper cells are co-best for a task in the archived final population, not necessarily correct answers.</p><div class="sx-table-scroll"><svg :width="agent.method.tasks * 4 + 80" :height="agent.method.population.length * 16 + 30" role="img" aria-label="Final-population task-winner coverage heatmap"><g v-for="(row, index) in agent.method.population" :key="row.index" :transform="`translate(0,${index * 16 + 18})`"><text x="2" y="10" fill="currentColor" font-size="10">P{{ row.index }}</text><rect v-for="(covered, task) in row.coverage" :key="task" :x="50 + Number(task) * 4" y="0" width="3" height="12" :fill="covered ? '#b65b3b' : '#9da6ae'" :opacity="covered ? 1 : .22"><title>P{{ row.index }} · Dev task {{ Number(task) + 1 }} · {{ covered ? 'co-best' : 'below task best' }}</title></rect></g></svg></div><p class="sx-note">Coverage is derived from the saved per-task scores. This is the final population, not a claim to preserve every intermediate frontier.</p></section>
    <section class="sx-panel"><div class="sx-control-row"><label>Population member<select v-model="active"><option v-for="(row, index) in agent.method.population" :key="row.index" :value="index">P{{ row.index }} · {{ pct(row.score) }} · {{ row.coverageWins }} co-best tasks</option></select></label><button class="sx-button" @click="$emit('inspect', member.id)">Instruction diff ↗</button><span v-if="selectedLabel(member)" class="sx-badge good">{{ selectedLabel(member) }}</span></div><div class="sx-flow"><div><small>Recorded parents</small><strong>{{ member.parents.length ? member.parents.map((id: number) => 'P' + id).join(' + ') : 'Seed' }}</strong></div><span>→</span><div><small>Dev mean</small><strong>{{ pct(member.score) }}</strong></div><span>→</span><div><small>Co-best coverage</small><strong>{{ member.coverageWins }} / {{ agent.method.tasks }}</strong></div></div><pre><code>{{ member.text }}</code></pre><details><summary>Recorded parent selections · {{ choices.length }} iterations sampled P{{ member.index }}</summary><div class="sx-table-scroll"><table><thead><tr><th>Iteration</th><th>Decision</th><th>Reason</th><th>Candidate mean</th></tr></thead><tbody><tr v-for="row in choices" :key="row.iteration"><td>{{ row.iteration }}</td><td>{{ row.kind }}</td><td>{{ row.reason || 'See recorded decision' }}</td><td>{{ pct(row.score) }}</td></tr></tbody></table></div></details></section>
    <section class="sx-panel"><h3>Final selection</h3><p class="sx-note">Parent sampling reflects task coverage; the recorded final artifact is selected separately by mean score. Highlighting below follows that artifact.</p><div class="sx-table-scroll"><table><thead><tr><th>Member</th><th>Mean dev</th><th>Co-best tasks</th><th>Final artifact</th></tr></thead><tbody><tr v-for="row in agent.method.population" :key="row.index" :class="{ 'sx-selected-row': row.finalContent }"><td>P{{ row.index }}</td><td>{{ pct(row.score) }}</td><td>{{ row.coverageWins }}</td><td>{{ selectedLabel(row) || 'Not selected' }}</td></tr></tbody></table></div></section>
  </div>
</template>
